import org.junit.jupiter.api.Test;

class PackedCorrelatedRegionOwnershipTest {

	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();

	@Test
	void independentAssuredAliasRegionOwnsItsUnchangedCyclePrefix() {
		PackedQuery query = PackedQueryCodec.encodeForPlanning(cycleWithAlias());
		PackedJoinEnumerator enumerator = enumerator(query);
		int root = query.rootRelId();
		int cycle = query.relChild(query.relChild(root, 0), 0);
		var outer = region(enumerator, root);
		var inner = region(enumerator, cycle);
		assertEquals(PackedNodeMetadataArena.INPUT_FRAME_SENSITIVE, outer.semanticScopeId());
		assertEquals(0, inner.semanticScopeId());
		assertEquals(outer.executionDomainId(), inner.executionDomainId());
		assertFalse((query.relMetadataFlags(root) & PackedNodeMetadataArena.UNKNOWN_OUTPUT_DOMAIN) != 0);
		assertFalse((query.relMetadataFlags(cycle) & PackedNodeMetadataArena.UNKNOWN_OUTPUT_DOMAIN) != 0);
		assertEquals(6, outer.factorRelationIds().length);
		assertEquals(5, inner.factorRelationIds().length);
		assertTrue(containsEveryOccurrence(outer.factorRelationIds(), inner.factorRelationIds()));
		assertFalse(query.masksIntersect(query.relOrdinaryWriteMaskId(root), query.relOutputMaskId(cycle)),
				"the preserved optAlias write is independent of all cycle bindings");
		assertTrue(query.relOrdinaryWriteMaskId(root) != 0, "the outer write facts must remain present");
		assertTrue(outer.strictlyContains(inner, query),
				"an independent outer alias phase can own the exact unchanged cycle prefix");
	}

	@Test
	void outsideWriterOfAPrefixOutputCannotOwnTheCrossFramePrefix() {
		Filter child = new Filter(new Join(pattern("z", "urn:first", "y"), pattern("y", "urn:second", "t")),
				new Bound(Var.of("y")));
		Extension writer = new Extension(new SingletonSet(),
				new ExtensionElem(new ValueConstant(VF.createLiteral("replacement")), "z"));
		PackedQuery query = PackedQueryCodec.encodeForPlanning(new Filter(new Join(writer, child),
				new Bound(Var.of("y"))));
		PackedJoinEnumerator enumerator = enumerator(query);
		int root = query.rootRelId();
		int childId = query.relChild(query.relChild(root, 0), 1);
		var outer = region(enumerator, root);
		var inner = region(enumerator, childId);
		assertEquals(PackedNodeMetadataArena.INPUT_FRAME_SENSITIVE, outer.semanticScopeId());
		assertEquals(0, inner.semanticScopeId());
		assertTrue(containsEveryOccurrence(outer.factorRelationIds(), inner.factorRelationIds()));
		assertTrue(query.masksIntersect(query.relOrdinaryWriteMaskId(root), query.relOutputMaskId(childId)),
				"z is a real prefix compatibility binding, even though both predicates read only y");
		assertFalse(outer.strictlyContains(inner, query),
				"structural membership cannot erase the original z writer/input phase");
	}

	@Test
	void nameAndFactorLocalAliasRemainDistinctOuterSearchSpaces() {
		PackedQuery query = PackedQueryCodec.encodeForPlanning(cycleWithAlias());
		PackedJoinEnumerator enumerator = enumerator(query);
		var original = region(enumerator, query.rootRelId());
		PackedJoinEnumerator.RelocatableFilterRegion commuted = null;
		for (int id = 1; id <= query.relationCount(); id++) {
			if (id == query.rootRelId() || query.relOperator(id) != PackedRelOp.FILTER) {
				continue;
			}
			var candidate = enumerator.describeRelocatableFilterRegion(id);
			if (candidate != null && candidate.factorRelationIds().length == original.factorRelationIds().length
					&& !hasExtensionFactor(query, candidate)) {
				commuted = candidate;
				break;
			}
		}
		assertNotNull(commuted, "real assured-alias commutation must expose the independent name-factor space");
		assertTrue(hasExtensionFactor(query, original));
		assertEquals(PackedNodeMetadataArena.INPUT_FRAME_SENSITIVE, original.semanticScopeId());
		assertEquals(original.semanticScopeId(), commuted.semanticScopeId());
		assertEquals(original.executionDomainId(), commuted.executionDomainId());
		assertFalse(original.hasSameSearchSpace(commuted));
		assertFalse(original.strictlyContains(commuted, query));
		assertFalse(commuted.strictlyContains(original, query));
	}

	private static Filter cycleWithAlias() {
		BindingSetAssignment selected = new BindingSetAssignment();
		selected.setBindingNames(Set.of("b"));
		selected.setBindingSets(List.of(new ListBindingSet(List.of("b"), VF.createIRI("urn:user"))));
		TupleExpr cycle = selected;
		for (StatementPattern pattern : List.of(pattern("a", "urn:follows", "b"),
				pattern("b", "urn:follows", "c"), pattern("c", "urn:follows", "d"),
				pattern("d", "urn:follows", "a"))) {
			cycle = new Join(cycle, pattern);
		}
		cycle = new Filter(cycle, new Compare(Var.of("a"), Var.of("b"), Compare.CompareOp.NE));
		cycle = new Filter(cycle, new Compare(Var.of("b"), Var.of("c"), Compare.CompareOp.NE));
		cycle = new Filter(cycle, new Compare(Var.of("c"), Var.of("d"), Compare.CompareOp.NE));
		cycle = new Filter(cycle, new Compare(Var.of("d"), Var.of("a"), Compare.CompareOp.NE));
		Extension alias = new Extension(pattern("b", "urn:name", "optName"),
				new ExtensionElem(Var.of("optName"), "optAlias"));
		return new Filter(new Join(cycle, alias),
				new Compare(Var.of("optAlias"), new ValueConstant(VF.createLiteral("")), Compare.CompareOp.NE));
	}

	private static StatementPattern pattern(String subject, String predicate, String object) {
		return new StatementPattern(Var.of(subject), Var.of(predicate, VF.createIRI(predicate), true, true),
				Var.of(object));
	}

	private static PackedJoinEnumerator enumerator(PackedQuery query) {
		int count = query.relationCount();
		PackedMemo memo = new PackedMemo(query, query.symbolCount(), count, count, 4, count, count * 2);
		return new PackedJoinEnumerator(query, memo, new double[count + 1],
				new PackedSearchBudget(PackedPlannerLimits.unbounded()), (PackedCostModel) null);
	}

	private static PackedJoinEnumerator.RelocatableFilterRegion region(PackedJoinEnumerator enumerator, int id) {
		var region = enumerator.describeRelocatableFilterRegion(id);
		assertNotNull(region, "real region must pass predicate/write ownership admission at relation " + id);
		return region;
	}

	private static boolean hasExtensionFactor(PackedQuery query,
			PackedJoinEnumerator.RelocatableFilterRegion region) {
		for (int factor : region.factorRelationIds()) {
			if (query.relOperator(factor) == PackedRelOp.EXTENSION) {
				return true;
			}
		}
		return false;
	}

	private static boolean containsEveryOccurrence(int[] source, int[] target) {
		boolean[] used = new boolean[source.length];
		for (int member : target) {
			boolean found = false;
			for (int ordinal = 0; ordinal < source.length; ordinal++) {
				if (!used[ordinal] && source[ordinal] == member) {
					used[ordinal] = true;
					found = true;
					break;
				}
			}
			if (!found) {
				return false;
			}
		}
		return true;
	}
}
